mapper.select:
SELECT 
FROM org_department
WHERE id = #{id} AND tenant_id = #{tenantId} AND is_deleted = #{deleted}

mapper.update:
UPDATE org_department
SET path = CONCAT(#{newPrefix}, SUBSTRING(path, LENGTH(#{oldPrefix}) + 1)),
    gmt_modified = NOW()
WHERE tenant_id = #{tenantId}
  AND is_deleted = #{deleted}
  AND path LIKE CONCAT(#{oldPrefix}, '%')

mapper.select:
SELECT COUNT(*)
FROM org_department
WHERE parent_id = #{parentId} AND tenant_id = #{tenantId} AND is_deleted = #{deleted}
